-- Row-level security on store_id (ADR 0039, D164-D168). The store scope of a connection is three settings the
-- backend writes at every checkout (D165): app.all_stores ('on'/'off'), app.store_ids (a canonical uuid[] literal)
-- and app.scope_origin (diagnostics only). '' or never set = unset: the two readers below then raise RS001, so a code
-- path that forgot its scope fails loudly instead of reading nothing (P63). Every policy is generated by the helpers
-- below, so all protected tables carry the same canonical text (RowLevelSecurityCoverageTest compares it). Policies
-- are TO PUBLIC and no migration names a role: the superuser and restaurantpro_owner bypass RLS, so the policies
-- bind exactly the application role (D163). This migration protects no module table; each module's slice does.

CREATE FUNCTION shared.rls_scope_origin() RETURNS text
    LANGUAGE sql STABLE PARALLEL SAFE AS
$$
SELECT coalesce(nullif(current_setting('app.scope_origin', true), ''), 'none')
$$;

-- Whether the scope is every store. Raises RS001 when unset or malformed (fail closed).
CREATE FUNCTION shared.rls_all_stores() RETURNS boolean
    LANGUAGE plpgsql STABLE PARALLEL SAFE AS
$$
DECLARE
    v_all text := current_setting('app.all_stores', true);
BEGIN
    IF v_all = 'on' THEN
        RETURN true;
    ELSIF v_all = 'off' THEN
        RETURN false;
    END IF;
    RAISE EXCEPTION USING ERRCODE = 'RS001',
        MESSAGE = format('store scope not set (origin %s)', shared.rls_scope_origin());
END;
$$;

-- The stores of the scope (meaningful when app.all_stores is off). Raises RS001 when unset.
CREATE FUNCTION shared.rls_store_ids() RETURNS uuid[]
    LANGUAGE plpgsql STABLE PARALLEL SAFE AS
$$
DECLARE
    v_ids text := current_setting('app.store_ids', true);
BEGIN
    IF v_ids IS NULL OR v_ids = '' THEN
        RAISE EXCEPTION USING ERRCODE = 'RS001',
            MESSAGE = format('store scope not set (origin %s)', shared.rls_scope_origin());
    END IF;
    RETURN v_ids::uuid[];
END;
$$;

-- Trigger: a row never moves to another store, whatever the scope (D168); also a child's parent key.
CREATE FUNCTION shared.rls_reject_scope_change() RETURNS trigger
    LANGUAGE plpgsql AS
$$
BEGIN
    RAISE EXCEPTION USING ERRCODE = 'RS002',
        MESSAGE = format('store change refused on %I.%I (origin %s)', TG_TABLE_SCHEMA, TG_TABLE_NAME,
                         shared.rls_scope_origin());
END;
$$;

-- The canonical visibility test VIS(column) of D168. The (SELECT ...) wrappers make each reader an InitPlan,
-- evaluated once per statement.
CREATE FUNCTION shared.rls_visible(p_store_column text) RETURNS text
    LANGUAGE sql IMMUTABLE AS
$$
SELECT format('((SELECT shared.rls_all_stores()) OR %s = ANY ((SELECT shared.rls_store_ids())::uuid[]))',
              p_store_column)
$$;

-- PROTECTED: every table a policy slice protected, written by the helpers below (and by rls_register_protected for
-- the SPECIAL tables with hand-written policies). The startup check refuses to start when a registered table lost
-- ENABLE, FORCE or its policies, so losing every policy of a schema (a restore without policies) is caught too.
CREATE TABLE shared.rls_protected_table
(
    table_name regclass NOT NULL,
    CONSTRAINT rls_protected_table_pk PRIMARY KEY (table_name)
);
ALTER TABLE shared.rls_protected_table ENABLE ROW LEVEL SECURITY;
ALTER TABLE shared.rls_protected_table FORCE ROW LEVEL SECURITY;
CREATE POLICY registry_read ON shared.rls_protected_table AS PERMISSIVE FOR SELECT TO PUBLIC USING (true);

-- For a SPECIAL table (D168: audit_event, stock_transfer, warehouse) after its own policies are created.
CREATE FUNCTION shared.rls_register_protected(p_table regclass) RETURNS void
    LANGUAGE sql AS
$$
INSERT INTO shared.rls_protected_table (table_name)
VALUES (p_table)
ON CONFLICT (table_name) DO NOTHING
$$;

CREATE FUNCTION shared.rls_require_store_column(p_table regclass) RETURNS void
    LANGUAGE plpgsql AS
$$
BEGIN
    IF NOT EXISTS (SELECT 1
                   FROM pg_catalog.pg_attribute a
                   WHERE a.attrelid = p_table
                     AND a.attname = 'store_id'
                     AND a.atttypid = 'uuid'::regtype
                     AND NOT a.attisdropped) THEN
        RAISE EXCEPTION '% has no uuid store_id column', p_table USING ERRCODE = 'invalid_parameter_value';
    END IF;
END;
$$;

-- STORE: the row belongs to one store (store_id NOT NULL).
CREATE FUNCTION shared.rls_protect_store_table(p_table regclass) RETURNS void
    LANGUAGE plpgsql AS
$$
BEGIN
    PERFORM shared.rls_require_store_column(p_table);
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', p_table);
    EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', p_table);
    EXECUTE format('CREATE POLICY store_scope ON %s AS PERMISSIVE FOR ALL TO PUBLIC USING (%s) WITH CHECK (%s)',
                   p_table, shared.rls_visible('store_id'), shared.rls_visible('store_id'));
    EXECUTE format('CREATE TRIGGER store_scope_fixed BEFORE UPDATE OF store_id ON %s FOR EACH ROW '
                       || 'WHEN (OLD.store_id IS DISTINCT FROM NEW.store_id) '
                       || 'EXECUTE FUNCTION shared.rls_reject_scope_change()', p_table);
    PERFORM shared.rls_register_protected(p_table);
END;
$$;

-- STORE_OR_ALL: store_id NULL means every store. Everyone in scope reads those rows; only an all-stores scope writes
-- them (NULL = ANY (...) is not true).
CREATE FUNCTION shared.rls_protect_store_or_all_table(p_table regclass) RETURNS void
    LANGUAGE plpgsql AS
$$
BEGIN
    PERFORM shared.rls_require_store_column(p_table);
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', p_table);
    EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', p_table);
    EXECUTE format('CREATE POLICY store_or_all_scope ON %s AS PERMISSIVE FOR ALL TO PUBLIC '
                       || 'USING (store_id IS NULL OR %s) WITH CHECK (%s)',
                   p_table, shared.rls_visible('store_id'), shared.rls_visible('store_id'));
    EXECUTE format('CREATE TRIGGER store_scope_fixed BEFORE UPDATE OF store_id ON %s FOR EACH ROW '
                       || 'WHEN (OLD.store_id IS DISTINCT FROM NEW.store_id) '
                       || 'EXECUTE FUNCTION shared.rls_reject_scope_change()', p_table);
    PERFORM shared.rls_register_protected(p_table);
END;
$$;

-- CHILD: no store_id; visible when its parent (same module, in-module foreign key) is in scope. The store is checked
-- on the parent explicitly, not only through the parent's own policy (warehouse reads are open, D168).
CREATE FUNCTION shared.rls_protect_child_table(p_table regclass, p_fk_column name, p_parent regclass,
                                               p_parent_key name) RETURNS void
    LANGUAGE plpgsql AS
$$
DECLARE
    v_visible text;
BEGIN
    PERFORM shared.rls_require_store_column(p_parent);
    v_visible := format('EXISTS (SELECT 1 FROM %s p WHERE p.%I = %s.%I AND %s)', p_parent, p_parent_key, p_table,
                        p_fk_column, shared.rls_visible('p.store_id'));
    EXECUTE format('ALTER TABLE %s ENABLE ROW LEVEL SECURITY', p_table);
    EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', p_table);
    EXECUTE format('CREATE POLICY parent_scope ON %s AS PERMISSIVE FOR ALL TO PUBLIC USING (%s) WITH CHECK (%s)',
                   p_table, v_visible, v_visible);
    EXECUTE format('CREATE TRIGGER parent_fixed BEFORE UPDATE OF %I ON %s FOR EACH ROW '
                       || 'WHEN (OLD.%I IS DISTINCT FROM NEW.%I) '
                       || 'EXECUTE FUNCTION shared.rls_reject_scope_change()', p_fk_column, p_table, p_fk_column,
                   p_fk_column);
    PERFORM shared.rls_register_protected(p_table);
END;
$$;

-- UNSCOPED: no policy, by decision, with its reason (D167). The coverage test and the startup check read this.
CREATE TABLE shared.rls_unscoped_table
(
    table_name regclass NOT NULL,
    reason     text     NOT NULL,
    CONSTRAINT rls_unscoped_table_pk PRIMARY KEY (table_name),
    CONSTRAINT rls_unscoped_table_reason_ck CHECK (btrim(reason) <> '')
);

-- The registry is written by migrations only (the owner bypasses RLS): the pool may read it, never change it, so a
-- compromised application cannot hide a table from the startup check.
ALTER TABLE shared.rls_unscoped_table ENABLE ROW LEVEL SECURITY;
ALTER TABLE shared.rls_unscoped_table FORCE ROW LEVEL SECURITY;
CREATE POLICY registry_read ON shared.rls_unscoped_table AS PERMISSIVE FOR SELECT TO PUBLIC USING (true);

CREATE FUNCTION shared.rls_register_unscoped(p_table regclass, p_reason text) RETURNS void
    LANGUAGE sql AS
$$
INSERT INTO shared.rls_unscoped_table (table_name, reason)
VALUES (p_table, p_reason)
ON CONFLICT (table_name) DO UPDATE SET reason = excluded.reason
$$;

-- The D42 probe: another store's resource must still answer 403, not 404, so "read only its storeId" sees every store.
-- The one SECURITY DEFINER function besides inventory.stock_transfer_stores (D168): it refuses a table without RLS or
-- without a store_id, finds the single-column primary key in the catalog, and returns only that row's store_id (or
-- NULL). Every catalog name is schema-qualified: pg_temp is searched first when the path does not list it.
CREATE FUNCTION shared.store_of(t regclass, id uuid) RETURNS uuid
    LANGUAGE plpgsql
    STABLE
    SECURITY DEFINER
    SET search_path = pg_catalog AS
$$
DECLARE
    v_key   name;
    v_store uuid;
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_catalog.pg_class c WHERE c.oid = t AND c.relrowsecurity) THEN
        RAISE EXCEPTION 'shared.store_of: % has no row-level security', t USING ERRCODE = 'invalid_parameter_value';
    END IF;
    IF NOT EXISTS (SELECT 1
                   FROM pg_catalog.pg_attribute a
                   WHERE a.attrelid = t
                     AND a.attname = 'store_id'
                     AND a.atttypid = 'pg_catalog.uuid'::pg_catalog.regtype
                     AND NOT a.attisdropped) THEN
        RAISE EXCEPTION 'shared.store_of: % has no store_id', t USING ERRCODE = 'invalid_parameter_value';
    END IF;
    SELECT a.attname
    INTO v_key
    FROM pg_catalog.pg_index i
             JOIN pg_catalog.pg_attribute a ON a.attrelid = i.indrelid AND a.attnum = i.indkey[0]
    WHERE i.indrelid = t
      AND i.indisprimary
      AND i.indnatts = 1
      AND a.atttypid = 'pg_catalog.uuid'::pg_catalog.regtype;
    IF v_key IS NULL THEN
        RAISE EXCEPTION 'shared.store_of: % has no single-column uuid primary key', t
            USING ERRCODE = 'invalid_parameter_value';
    END IF;
    EXECUTE pg_catalog.format('SELECT store_id FROM %s WHERE %I = $1', t, v_key) INTO v_store USING id;
    RETURN v_store;
END;
$$;

-- The shared kernel's and public's tables (D167): the Modulith event registry is read at startup and by the D88
-- recovery, before any actor; idempotency records are keyed by the principal (D38); sessions are read before
-- authentication.
SELECT shared.rls_register_unscoped('public.event_publication',
                                    'Spring Modulith event registry: read at startup and by the D88 recovery, '
                                        || 'with no actor; never reaches a client');
SELECT shared.rls_register_unscoped('public.event_publication_archive',
                                    'Spring Modulith event registry archive: as event_publication');
SELECT shared.rls_register_unscoped('public.flyway_schema_history',
                                    'Flyway migration history: schema metadata');
SELECT shared.rls_register_unscoped('shared.idempotency_record',
                                    'Idempotency-Key records are keyed by the principal (D38); only a replay to '
                                        || 'the same principal reaches a client');
SELECT shared.rls_register_unscoped('shared.spring_session', 'Spring Session JDBC: read before authentication');
SELECT shared.rls_register_unscoped('shared.spring_session_attributes',
                                    'Spring Session JDBC attributes: read before authentication');
SELECT shared.rls_register_unscoped('shared.rls_unscoped_table',
                                    'This registry: read-only to the pool through its own read policy');
SELECT shared.rls_register_unscoped('shared.rls_protected_table',
                                    'The protected-table registry: read-only to the pool through its own read policy');

